import math

def f(x):
    return 1 / (1 + 1/(1 + 1/x))

# Find values that make any denominator zero
# Denominators: D1 = x, D2 = 1+x, D3 = 1+1/x
solutions = []
if x == 0: solutions.append(0)
if 1 + x == 0: solutions.append(-1)
if 1 + 1/x == 0:
    # solve 1 + 1/x = 0 => 1/x = -1 => x = -1
    solutions.append(-1)
# Remove duplicates
distinct = list(set(solutions))
print(sum(distinct))

def max_acute(n):
    total = (n-2)*180
    for k in range(n+1):
        m = n - k
        # acute angles can be arbitrarily close to 0, but must be <90; we test with a small epsilon
        if remaining_needed := total - k * 89 <= m * 180:
            return k
    return 0
print(max_acute(10))

